func newExportCmd(flags *rootFlags) *cobra.Command {
	var format string
	var outputFile string
	var limit int
	var noCache bool

	cmd := &cobra.Command{
		Use:   "export <resource> [id]",
		Short: "Export data to JSONL or JSON for backup, migration, or analysis",
		Long: `Export paginated API data to a local file. Supports JSONL (one JSON object
per line, streaming-friendly) and JSON (array). JSONL is recommended for
large datasets as it has no memory pressure.`,
		Example: `  # Export all items as JSONL (streaming, recommended for large datasets)
  fedex-pp-cli export <resource> --format jsonl --output data.jsonl

  # Export with limit
  fedex-pp-cli export <resource> --format jsonl --limit 1000

  # Pipe to another tool
  fedex-pp-cli export <resource> --format jsonl | jq '.id'`,
		Args: cobra.MinimumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			c, err := flags.newClient()
			if err != nil {
				return err
			}
			if noCache {
				c.NoCache = true
			}

			resource := args[0]
			path := "/" + resource
			if len(args) > 1 {
				path += "/" + args[1]
			}

			data, err := c.Get(path, nil)
			if err != nil {
				return classifyAPIError(err)
			}
			var output bytes.Buffer

			switch format {
			case "jsonl":
				var items []json.RawMessage
				if err := json.Unmarshal(data, &items); err != nil {
					fmt.Fprintln(&output, string(data))
					break
				}
				count := 0
				for _, item := range items {
					if limit > 0 && count >= limit {
						break
					}
					fmt.Fprintln(&output, string(item))
					count++
				}
			default:
				enc := json.NewEncoder(&output)
				enc.SetIndent("", "  ")
				var parsed any
				if err := json.Unmarshal(data, &parsed); err != nil {
					return err
				}
				if err := enc.Encode(parsed); err != nil {
					return err
				}
			}
			if outputFile != "" {
				if err := secureio.WriteFileAtomic(outputFile, output.Bytes()); err != nil {
					return fmt.Errorf("writing output file: %w", err)
				}
				fmt.Fprintf(cmd.ErrOrStderr(), "Exported data to %s\n", outputFile)
				return nil
			}
			if _, err := cmd.OutOrStdout().Write(output.Bytes()); err != nil {
				return fmt.Errorf("writing export output: %w", err)
			}
			return nil
		},
	}

	cmd.Flags().StringVar(&format, "format", "jsonl", "Output format: jsonl or json")
	cmd.Flags().StringVarP(&outputFile, "output", "o", "", "Output file path (default: stdout)")
	cmd.Flags().IntVar(&limit, "limit", 0, "Maximum records to export (0 = unlimited)")
	cmd.Flags().BoolVar(&noCache, "no-cache", false, "Bypass response cache for fresh data")

	return cmd
}
